UPDATE "City" SET "published" = 1 WHERE "slug" IN ('orlando', 'west-palm-beach', 'newark', 'boise');
UPDATE "City" SET "intro" = 'Orlando has a club, an event organizer and city-run play. Orlando Mah Jongg Club hosts weekly games at venues around the area, and Mahj & Away runs hosted evenings and beginner lessons. The City of Orlando offers a Tuesday American Mahjong session at Beardall Senior Center, and local cafes and wine bars host open play and introductory classes. Games are spread across the metro, so check the address, and RSVP where it is required.' WHERE "slug" = 'orlando';
UPDATE "City" SET "intro" = 'Palm Beach County listings center on the Boca Raton History Museum, which runs American Mahjong classes and open play through the fall. Morning sessions and a Mahjong 101 evening class are good starting points for beginners, and a Mahjong 102 class follows for players who know the basics. Pick the session that fits your schedule and check the museum''s page for registration details.' WHERE "slug" = 'west-palm-beach';
UPDATE "City" SET "intro" = 'New Jersey listings come from a community center and a teaching organizer. CASA Essex in Newark hosts a guided open-play series using National Mah Jongg League rules, welcoming newcomers and experienced players. Keep Mahjing On, run by Shanna Gottlieb, offers lessons and guided open play at cafes and studios across the state, including Montclair and Hoboken. Locations vary, so check each event''s address before you go.' WHERE "slug" = 'newark';
UPDATE "City" SET "intro" = 'Boise''s American Mahjong is centered on beginner classes. Mahjong at the Local teaches a two-part introductory series at LOCAL Boise, downtown, using the National Mah Jongg League card, and OK LET''S MAHJONG offers private lessons and community events. If you are new, the two-part series is the natural place to start. Check each event page for dates and registration.' WHERE "slug" = 'boise';
